#include "turbulentDFMVeerInletFvPatchVectorField.H"
#include "addToRunTimeSelectionTable.H"
#include "fvPatchFieldMapper.H"
#include "volFields.H"
#include "IFstream.H"
#include "mathematicalConstants.H"
#include <algorithm>

namespace Foam
{

// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //

defineTypeNameAndDebug(turbulentDFMVeerInletFvPatchVectorField, 0)
makePatchTypeField
(
 fvPatchVectorField
 turbulentDFMVeerInletFvPatchVectorField
)
// * * * * * * * * * * * * * * * * Constructors * * * * * * * * * * * * * * //

turbulentDFMVeerInletFvPatchVectorField::turbulentDFMVeerInletFvPatchVectorField
(
 const fvPatch& p
 const DimensionedField<vector, volMesh>& iF
)
:
 fixedValueFvPatchVectorField(p, iF)
 filterType_("exponential")
 filterFactor_(4.0)
 periodicInY_(false)
 periodicInZ_(false)
 constMeanU_(true)
 Uref_(10.6900)
 curTimeIndex_(-1)
 rnd_(1234)
 initialized_(false)
{}


turbulentDFMVeerInletFvPatchVectorField::turbulentDFMVeerInletFvPatchVectorField
(
 const fvPatch& p
 const DimensionedField<vector, volMesh>& iF
 const dictionary& dict
)
:
 fixedValueFvPatchVectorField(p, iF, dict, false)
 filterType_(dict.lookupOrDefault<word>("filterType", "exponential"))
 filterFactor_(dict.lookupOrDefault<scalar>("filterFactor", 4.0))
 periodicInY_(dict.lookupOrDefault<bool>("periodicInY", false))
 periodicInZ_(dict.lookupOrDefault<bool>("periodicInZ", false))
 constMeanU_(dict.lookupOrDefault<bool>("constMeanU", true))
 Uref_(dict.lookupOrDefault<scalar>("Uref", 10.6900))
 curTimeIndex_(-1)
 rnd_(1234)
 initialized_(false)
{
 if (dict.found("value"))
 {
 fvPatchField<vector>::operator=
 (
 vectorField("value", dict, p.size)
)
 }
 else
 {
 fvPatchField<vector>::operator=(vector::zero)
 }
}


turbulentDFMVeerInletFvPatchVectorField::turbulentDFMVeerInletFvPatchVectorField
(
 const turbulentDFMVeerInletFvPatchVectorField& ptf
 const fvPatch& p
 const DimensionedField<vector, volMesh>& iF
 const fvPatchFieldMapper& mapper
)
:
 fixedValueFvPatchVectorField(ptf, p, iF, mapper)
 filterType_(ptf.filterType_)
 filterFactor_(ptf.filterFactor_)
 periodicInY_(ptf.periodicInY_)
 periodicInZ_(ptf.periodicInZ_)
 constMeanU_(ptf.constMeanU_)
 Uref_(ptf.Uref_)
 curTimeIndex_(-1)
 rnd_(ptf.rnd_)
 initialized_(false)
{}


turbulentDFMVeerInletFvPatchVectorField::turbulentDFMVeerInletFvPatchVectorField
(
 const turbulentDFMVeerInletFvPatchVectorField& ptf
)
:
 fixedValueFvPatchVectorField(ptf)
 filterType_(ptf.filterType_)
 filterFactor_(ptf.filterFactor_)
 periodicInY_(ptf.periodicInY_)
 periodicInZ_(ptf.periodicInZ_)
 constMeanU_(ptf.constMeanU_)
 Uref_(ptf.Uref_)
 curTimeIndex_(ptf.curTimeIndex_)
 rnd_(ptf.rnd_)
 initialized_(false)
{}


turbulentDFMVeerInletFvPatchVectorField::turbulentDFMVeerInletFvPatchVectorField
(
 const turbulentDFMVeerInletFvPatchVectorField& ptf
 const DimensionedField<vector, volMesh>& iF
)
:
 fixedValueFvPatchVectorField(ptf, iF)
 filterType_(ptf.filterType_)
