 os.writeEntryIfDifferent<scalar>("filterFactor", 4.0, filterFactor_)
 os.writeEntryIfDifferent<bool>("periodicInY", false, periodicInY_)
 os.writeEntryIfDifferent<bool>("periodicInZ", false, periodicInZ_)
