 scalar z0 = sortedZ[low]
 scalar z1 = sortedZ[high]
 scalar w = (zf - z0) / max(z1 - z0, 1e-12)
 label k0 = sortIdx[low]
 label k1 = sortIdx[high]
 uVal = (1.0 - w) * rawU[k0] + w * rawU[k1]
 psiVal = (1.0 - w) * rawPsiDeg[k0] + w * rawPsiDeg[k1]
 rVal = (1.0 - w) * rawR[k0] + w * rawR[k1]
 lVal = (1.0 - w) * rawL[k0] + w * rawL[k1]
 }

 U_mean_[fI] = uVal
 psi_rad_[fI] = psiVal * deg2rad
 R_local_[fI] = rVal
 L_local_[fI] = lVal
 // 计算当地雷诺应力张量的 Cholesky 分解矩阵 A (保证对称正定鲁棒性)
 scalar rxx = max(rVal.xx, 1e-6)
 scalar a11 = sqrt(rxx)
 scalar a21 = rVal.xy / a11
 scalar a22_sq = rVal.yy - a21 * a21
 scalar a22 = sqrt(max(a22_sq, 1e-6))
 scalar a31 = rVal.xz / a11
 scalar a32 = (rVal.yz - a21 * a31) / a22
 scalar a33_sq = rVal.zz - a31 * a31 - a32 * a32
 scalar a33 = sqrt(max(a33_sq, 1e-6))
 // 存为 tensor:
 // row 0: a11, 0, 0
 // row 1: a21, a22, 0
 // row 2: a31, a32, a33
 A_chol_[fI] = tensor
 (
 a11, 0.0, 0.0
 a21, a22, 0.0
 a31, a32, a33
)
 }

 // 预构建空间滤波卷积核
 buildFilterKernel
 // 初始化时间 AR(1) 状态向量
 v_state_.setSize(nFaces, Zero)
 initialised_ = true
}

void turbulentDFMVeerInletFvPatchVectorField::buildFilterKernel
{
 const label nFaces = this->patch.size
 const vectorField& Cf = this->patch.Cf
 // 确定 patch 的 Y 方向跨度，用于周期性距离计算
 scalar yMin = GREAT
 scalar yMax = -GREAT
 forAll(Cf, i)
 {
 yMin = min(yMin, Cf[i].y)
 yMax = max(yMax, Cf[i].y)
 }
 const scalar Ly = max(yMax - yMin, 1e-6)
 filterIndices_.setSize(3)
 filterWeights_.setSize(3)
 for (label c = 0; c < 3; ++c)
 {
 filterIndices_[c].setSize(nFaces)
 filterWeights_[c].setSize(nFaces)
 for (label i = 0; i < nFaces; ++i)
 {
 const scalar yi = Cf[i].y
 const scalar zi = Cf[i].z
 const scalar psi_i = psi_rad_[i]
 const scalar cosPsi = cos(psi_i)
 // 当地各分量积分尺度
 // c=0(u'): Ly=L_local.xy, Lz=L_local.xz
 // c=1(v'): Ly=L_local.yy, Lz=L_local.yz
 // c=2(w'): Ly=L_local.zy, Lz=L_local.zz
 scalar Ly_scale = 1.0
 scalar Lz_scale = 1.0
 if (c == 0)
 {
 Ly_scale = max(L_local_[i].xy, 1e-3)
 Lz_scale = max(L_local_[i].xz, 1e-3)
 }
 else if (c == 1)
 {
 Ly_scale = max(L_local_[i].yy, 1e-3)
 Lz_scale = max(L_local_[i].yz, 1e-3)
 }
 else
 {
 Ly_scale = max(L_local_[i].zy, 1e-3)
 Lz_scale = max(L_local_[i].zz, 1e-3)
 }

 // 截断作用范围半径
 scalar maxDy = filterFactor_ * Ly_scale / max(mag(cosPsi), 0.1)
 scalar maxDz = filterFactor_ * Lz_scale
 DynamicList<label> nbrList
 DynamicList<scalar> wList
 scalar sumSq = 0.0
 for (label j = 0; j < nFaces; ++j)
 {
 scalar dy = mag(yi - Cf[j].y)
 if (periodicInY_)
 {
 dy = min(dy, Ly - dy)
 }

 scalar dz = mag(zi - Cf[j].z)
 if (dy <= maxDy && dz <= maxDz)
 {
 // 在当地风向坐标系中，入口面上横向位移在 y' 轴上的投影距离为 dy * cos(psi)
 scalar dy_local = dy * mag(cosPsi)
 scalar b = exp
 (
 - constant::mathematical::pi * (dy_local / Ly_scale)
 - constant::mathematical::pi * (dz / Lz_scale)
)
 nbrList.append(j)
 wList.append(b)
 sumSq += b * b
 }
 }

 // 能量守恒归一化: sum(b_norm^2) = 1
 scalar invNorm = 1.0 / sqrt(max(sumSq, 1e-12))
 scalarList& finalW = filterWeights_[c][i]
 labelList& finalIdx = filterIndices_[c][i]
 finalW.setSize(wList.size)
 finalIdx.setSize(nbrList.size)
 forAll(wList, k)
 {
 finalW[k] = wList[k] * invNorm
 finalIdx[k] = nbrList[k]
 }
 }
 }
}

void turbulentDFMVeerInletFvPatchVectorField::calculateInflow
{
 const label nFaces = this->patch.size
 const scalar dt = this->db.time.deltaTValue
 // 1. 生成 3 个互不相关的空间标准正态随机白噪声场
 List<scalarField> whiteNoise(3)
 for (label c = 0; c < 3; ++c)
 {
 whiteNoise[c].setSize(nFaces)
 for (label i = 0; i < nFaces; ++i)
 {
 whiteNoise[c][i] = rndGen_.GaussNormal<scalar>
 }
 }

 // 2. 空间滤波与时间自回归合成
 vectorField U_new(nFaces, Zero)
 for (label i = 0; i < nFaces; ++i)
 {
 vector psi_filt(Zero)
 // 空间数字滤波卷积
 for (label c = 0; c < 3; ++c)
 {
 const labelList& nbrs = filterIndices_[c][i]
 const scalarList& w = filterWeights_[c][i]
 scalar val = 0.0
 forAll(nbrs, k)
 {
 val += w[k] * whiteNoise[c][nbrs[k]]
 }
 psi_filt[c] = val
 }

 // 时间自相关 AR(1) 过程
 // 欧拉时间尺度 tau_i = L_ix' / U_mean
 scalar Uloc = max(U_mean_[i], 1e-2)
 scalar tau_u = max(L_local_[i].xx / Uloc, 1e-4)
 scalar tau_v = max(L_local_[i].yx / Uloc, 1e-4)
 scalar tau_w = max(L_local_[i].zx / Uloc, 1e-4)
 vector rho
 (
 exp(-constant::mathematical::pi * dt / (2.0 * tau_u))
 exp(-constant::mathematical::pi * dt / (2.0 * tau_v))
 exp(-constant::mathematical::pi * dt / (2.0 * tau_w))
)
 if (curTimeIndex_ <= 1)
 {
 v_state_[i] = psi_filt
 }
 else
 {
 for (label c = 0; c < 3; ++c)
 {
 scalar r = rho[c]
 scalar oneMinusR2 = max(1.0 - r * r, 0.0)
 v_state_[i][c] = r * v_state_[i][c] + sqrt(oneMinusR2) * psi_filt[c]
 }
 }

 // 3. Lund 变换: 当地坐标脉动 u'_local = A * v
 const tensor& A = A_chol_[i]
 const vector& v = v_state_[i]
 vector u_prime_local
 (
 A.xx * v.x
 A.yx * v.x + A.yy * v.y
 A.zx * v.x + A.zy * v.y + A.zz * v.z
)
 // 4. 旋转至全局笛卡尔坐标系
 scalar theta = psi_rad_[i]
 scalar cosT = cos(theta)
 scalar sinT = sin(theta)
 // 全局平均速度矢量
 vector U_avg(U_mean_[i] * cosT, U_mean_[i] * sinT, 0.0)
 // 全局脉动速度矢量 (u_global = Q * u'_local)
 vector u_prime_global
 (
 u_prime_local.x * cosT - u_prime_local.y * sinT
 u_prime_local.x * sinT + u_prime_local.y * cosT
 u_prime_local.z
)
 // 总速度叠加
 U_new[i] = U_avg + u_prime_global
 }

 // 赋值给本边界条件 patch 面场
 this->operator==(U_new)
}

