void Foam::turbulentDFMVeerInletFvPatchVectorField::initialise
{
 initialisePatch
 initialiseParameters
 initialiseVirtualGrid
 initialiseFilterCoeff
 initialiseOutput
 if (isRestart_ && !isCleanRestart_)
 {
 uFluctTemporalOld_ = uFluctTemporal_
 }
 else
 {
 spatialCorr
 uFluctTemporalOld_ = uFluctFiltered_
 }
}

void Foam::turbulentDFMVeerInletFvPatchVectorField::updateCoeffs
{
 if (updated)
 {
 return
 }

 if (!isInitialized_)
 {
 initialise
 isInitialized_ = true
 }

 if (curTimeIndex_ != this->db.time.timeIndex)
 {
 curTimeIndex_ = db.time.timeIndex
 // 1. Generate spatial correlation
 spatialCorr
 // 2. Generate temporal correlation
 temporalCorr
 // 3. Compose final velocity with wind veer
 vectorField& U = *this
 const scalar degToRad = constant::mathematical::pi / 180.0
 vectorField Umean(patch.size, vector::zero)
 forAll(U, faceI)
 {
 const scalar psiRad = psi_[faceI] * degToRad
 const scalar cosPsi = Foam::cos(psiRad)
 const scalar sinPsi = Foam::sin(psiRad)
 // Local mean velocity vector: U(z) * (cos(psi), sin(psi), 0)
 Umean[faceI] = U_[faceI] * vector(cosPsi, sinPsi, 0.0)
 // Local wind-aligned fluctuations: u'_local = Lund & uFluctTemporal
 const vector uFluctLocal = Lund_[faceI] & uFluctTemporal_[faceI]
 // Transform fluctuations from local wind frame to global Cartesian frame:
 // u_x = u'_x * cos(psi) - u'_y * sin(psi)
 // u_y = u'_x * sin(psi) + u'_y * cos(psi)
 // u_z = u'_z
 const vector uFluctGlobal
 (
 uFluctLocal.x*cosPsi - uFluctLocal.y*sinPsi
 uFluctLocal.x*sinPsi + uFluctLocal.y*cosPsi
 uFluctLocal.z
)
 // Instantaneous velocity before mass flux re-scaling
 U[faceI] = Umean[faceI] + uFluctGlobal
 }

 // 4. Re-scale to ensure exact target mass flow rate across the patch
 const scalar targetFlux = gSum(-Umean & patch.Sf)
 const scalar actualFlux = gSum(-U & patch.Sf)
 scalar fCorr = 1.0
 if (Foam::mag(actualFlux) > VSMALL)
 {
 fCorr = targetFlux / actualFlux
 }

 U *= fCorr
 if (Pstream::master)
 {
 Info<< "turbulentDFMVeerInlet mass flow correction coefficient: " << fCorr << endl
 }

 forAll(outputFaceIndices_, i)
 {
 writeValues(i, U[outputFaceIndices_[i]])
 }

 isRestart_ = true
 }

 fixedValueFvPatchVectorField::updateCoeffs
}

void Foam::turbulentDFMVeerInletFvPatchVectorField::write(Ostream& os) const
{
 fvPatchVectorField::write(os)
 writeEntry(os, "value", *this)
 writeEntryIfDifferent<bool>(os, "periodicInY", false, periodicInY_)
 writeEntryIfDifferent<bool>(os, "periodicInZ", false, periodicInZ_)
 writeEntryIfDifferent<bool>(os, "constMeanU", false, constMeanU_)
 writeEntry(os, "uFluctTemporal", uFluctTemporal_)
 writeEntry(os, "U", U_)
 writeEntry(os, "R", R_)
 writeEntry(os, "L", L_)
 writeEntry(os, "psi", psi_)
 writeEntry(os, "Uref", Uref_)
 writeEntryIfDifferent<scalar>(os, "gridFactor", 1.0, gridFactor_)
