void Foam::turbulentDFMVeerInletFvPatchVectorField::temporalCorr
{
 Info<< "Generating temporal correlation" << endl
 scalar dt = db.time.deltaT.value
 forAll(uFluctTemporal_, faceI)
 {
 // Unscaled streamwise integral length scales in local wind frame
 const vector L = vector(L_[faceI].xx, L_[faceI].yx, L_[faceI].zx)
 vector T = L/U_[faceI]
 if (constMeanU_)
 {
 T = L/Uref_
 }

 for (label ii = 0; ii <= 2; ii++)
 {
 uFluctTemporal_[faceI].component(ii) = 
 uFluctTemporalOld_[faceI].component(ii)*Foam::exp(-dt/T.component(ii))
 + uFluctFiltered_[faceI].component(ii)*Foam::sqrt(1.0 - Foam::exp(-2.0*dt/T.component(ii)))
 }
 }

 uFluctTemporalOld_ = uFluctTemporal_
 Info<< "Temporal correlation generated" << endl
}

Foam::scalar Foam::turbulentDFMVeerInletFvPatchVectorField::bessi0(const scalar x)
{
 scalar ax, ans, y
 if ((ax=fabs(x)) < 3.75) 
 {
 y = x/3.75
 y = y*y
 ans = 1.0+y*(3.5156229+y*(3.0899424+y*(1.2067492
 + y*(0.2659732+y*(0.360768e-1+y*0.45813e-2)))))
 } 
 else 
 {
 y = 3.75/ax
 ans = (exp(ax)[local path omitted](ax))*(0.39894228+y*(0.-1
 + y*(0.225319e-2+y*(-0.157565e-2+y*(0.916281e-2
 + y*(-0.-1+y*(0.-1+y*(-0.-1
 + y*0.392377e-2))))))))
 }
 return ans
}

