void Foam::turbulentDFMVeerInletFvPatchVectorField::updateCoeffs
{
 if (updated)
 {
 return
 }

 if (!isInitialized_)
 {
 initialise
 isInitialized_ = true
 }

 if (curTimeIndex_ != this->db.time.timeIndex)
 {
 Info<< "updating velocity at Time = " << db.time.value << endl
 curTimeIndex_ = db.time.timeIndex
 // 1. Spatially correlated 2D filtered random field
 spatialCorr
 // 2. Temporally correlated AR(1) slice
 temporalCorr
 // 3. Assemble wind-veered mean velocity and local fluctuating velocity
 vectorField& U = *this
 vectorField Umean(patch.size, vector::zero)
 const scalar degToRad = constant::mathematical::pi / 180.0
 const vector ez(0, 0, 1)
 const vector ex = patchNormal_; // Typically (+1, 0, 0)
 const vector ey = (ez ^ ex); // (0, 0, 1) ^ (1, 0, 0) = (0, 1, 0)

 forAll(U, faceI)
 {
 const scalar theta = psi_[faceI] * degToRad
 const scalar c = Foam::cos(theta)
 const scalar s = Foam::sin(theta)
 // Local wind-aligned orthonormal basis:
 // exPrime points along local mean wind direction
 // eyPrime points horizontally perpendicular to mean wind
 // ezPrime points vertically upward
 const vector exPrime = c*ex + s*ey
 const vector eyPrime = -s*ex + c*ey
 const vector ezPrime = ez
 // Mean velocity vector: U(z) * (cos psi, sin psi, 0)
 Umean[faceI] = U_[faceI] * exPrime
 // Fluctuations in local wind-aligned frame
 const vector uPrimeFluct = Lund_[faceI] & uFluctTemporal_[faceI]
 // Transform fluctuations from local wind frame to global frame:
 // u_global = u'_x * exPrime + u'_y * eyPrime + u'_z * ezPrime
 const vector uGlobalFluct = 
 uPrimeFluct.x * exPrime
 + uPrimeFluct.y * eyPrime
 + uPrimeFluct.z * ezPrime
 U[faceI] = Umean[faceI] + uGlobalFluct
 }

 // 4. Exact mass flow rate correction targeting the mean veered inflow flux
 // Note: patch.Sf points out of the computational domain
 // so (-U & Sf) is the positive inward mass flux.
 const scalar targetFlux = gSum(-Umean & patch.Sf)
 const scalar actualFlux = gSum(-U & patch.Sf)
 const scalar fCorr = targetFlux / actualFlux
 U *= fCorr
 if (Pstream::master)
 {
 Info<< "mass flow correction coefficient: " << fCorr << endl
 }

 forAll(outputFaceIndices_, i)
 {
 writeValues(i, U[outputFaceIndices_[i]])
 }

 isRestart_ = true
 }

 fixedValueFvPatchVectorField::updateCoeffs
}

