void Foam::turbulentDFMVeerInletFvPatchVectorField::createFiles
{
 if (nOutputFace_ > 0)
 {
 fileName baseDir = db.time.path
 word outputPrefix = "postProcessing"
 word prefix = "turbulentDFMVeerInlet"
 if (Pstream::parRun)
 {
 baseDir = baseDir/".."[local path omitted]
 }
 else
 {
 baseDir = baseDir/outputPrefix
 }

 const word startTimeName = db.time.timeName(db.time.startTime.value)
 label start = 0
 for (label i=0; i<Pstream::myProcNo; i++)
 {
 start += patchSize_[i]
 }

 forAll(outputFaceIndices_, i)
 {
 if (!filePtrs_.set(i))
 {
 fileName outputDir(baseDir/prefix/startTimeName)
 mkDir(outputDir)
 word fName(db.time.timeName(outputFaceIndices_[i]+start))
 IFstream is(outputDir/(fName + ".dat"))
 filePtrs_.set(i, new OFstream(outputDir/(fName + ".dat")))
 initStream(filePtrs_[i])
 writeFileHeader(i)
 }
 }
 }
}

void Foam::turbulentDFMVeerInletFvPatchVectorField::writeFileHeader(const label i)
{
 label start = 0
 for (label p=0; p<Pstream::myProcNo; p++)
 {
 start += patchSize_[p]
 }

 const label faceI = outputFaceIndices_[i]
 writeHeaderValue(filePtrs_[i], "face index", faceI + start)
 writeHeaderValue(filePtrs_[i], "face centroid", patch.Cf[faceI])
 writeHeaderValue(filePtrs_[i], "mean velocity magnitude", U_[faceI])
 writeHeaderValue(filePtrs_[i], "wind direction angle psi (deg)", psi_[faceI])
 writeHeaderValue(filePtrs_[i], "Reynolds stress tensor (local)", R_[faceI])
 writeHeaderValue(filePtrs_[i], "integral length scales (local)", L_[faceI])
 writeHeaderValue(filePtrs_[i], "synthetic method", "digital filtering with veer")
 writeHeaderValue(filePtrs_[i], "filter function", filterType_)
 writeCommented(filePtrs_[i], "Time")
 writeTabbed(filePtrs_[i], "ux")
 writeTabbed(filePtrs_[i], "uy")
 writeTabbed(filePtrs_[i], "uz")
 filePtrs_[i] << endl
}

void Foam::turbulentDFMVeerInletFvPatchVectorField::writeValues(const label i, const vector u)
{
 writeTime(filePtrs_[i])
 filePtrs_[i]
 << tab << u.component(vector::X)
 << tab << u.component(vector::Y)
 << tab << u.component(vector::Z) << endl
}

