void Foam::turbulentDFMVeerInletFvPatchVectorField::updateCoeffs
{
 if (updated)
 {
 return
 }

 if (!isInitialized_)
 {
 initialise
 isInitialized_ = true
 }

 if (curTimeIndex_ != this->db.time.timeIndex)
 {
 Info << "updating velocity at Time = " << db.time.value << endl
 curTimeIndex_ = db.time.timeIndex
 // 1. Filter random field
 spatialCorr
 // 2. Create new temporally correlated slice
 temporalCorr
 // 3. Assemble local mean and fluctuating velocities, then rotate to global coordinates
 const label nFaces = this->patch.size
 vectorField uMeanGlobal(nFaces, vector::zero)
 vectorField uFluctGlobal(nFaces, vector::zero)
 const scalar degToRad = constant::mathematical::pi / 180.0
 forAll(uMeanGlobal, faceI)
 {
 const scalar psiRad = psi_[faceI] * degToRad
 const scalar cosPsi = Foam::cos(psiRad)
 const scalar sinPsi = Foam::sin(psiRad)
 // 正交旋转张量 Q: 从当地风向坐标系 (x', y', z') 到全局坐标系 (x, y, z)
 const tensor Q
 (
 cosPsi, -sinPsi, 0.0
 sinPsi, cosPsi, 0.0
 0.0, 0.0, 1.0
)
 // 当地风向坐标系下的平均风: (U, 0, 0)
 const vector uMeanLocal(U_[faceI], 0.0, 0.0)
 // 当地风向坐标系下的脉动速度: B & v_temporal
 const vector uFluctLocal = Lund_[faceI] & uFluctTemporal_[faceI]
 // 变换至全局坐标系
 uMeanGlobal[faceI] = Q & uMeanLocal
 uFluctGlobal[faceI] = Q & uFluctLocal
 }

 // 4. 合成未修正的瞬时速度场
 vectorField& U = *this
 U = uMeanGlobal + uFluctGlobal
 // 5. 质量流量修正:
 // 目标通量为所设计的实际平均风场穿透入口面的总通量
 const scalar targetFlux = gSum(-uMeanGlobal & patch.Sf)
 const scalar actualFlux = gSum(-U & patch.Sf)
 scalar fCorr = 1.0
 if (Foam::mag(actualFlux) > VSMALL)
 {
 fCorr = targetFlux / actualFlux
 }

 U *= fCorr
 if (Pstream::master)
 {
 Info << "mass flow correction coefficient: " << fCorr << endl
 }

 forAll(outputFaceIndices_, i)
 {
 writeValues(i, U[outputFaceIndices_[i]])
 }

 isRestart_ = true
 }

 fixedValueFvPatchVectorField::updateCoeffs
}

