template<class Container>
void turbulentDFMVeerInletFvPatchVectorField::readBoundaryFile
(
 const fileName& fPath
 Container& values
)
{
 IFstream is(fPath)
 if (!is.good)
 {
 FatalErrorInFunction
 << "Cannot open file: " << fPath << nl
 << exit(FatalError)
 }

 token tok(is)
 if (tok.isWord && tok.wordToken == "FoamFile")
 {
 is.putBack(tok)
 dictionary headerDict(is)
 }
 else
 {
 is.putBack(tok)
 }

 is >> values
}


template<class Type>
Type turbulentDFMVeerInletFvPatchVectorField::interpolate1D
(
 const scalar z
 const scalarList& zGrid
 const List<Type>& data
) const
{
 const label n = zGrid.size
 if (n == 0)
 {
 FatalErrorInFunction << "Empty profile grid." << exit(FatalError)
 }
 if (z <= zGrid[0])
 {
 return data[0]
 }
 if (z >= zGrid[n - 1])
 {
 return data[n - 1]
 }

 auto it = std::lower_bound(zGrid.begin, zGrid.end, z)
 label idx = std::distance(zGrid.begin, it)
 if (idx <= 0) idx = 1
 if (idx >= n) idx = n - 1
 scalar z0 = zGrid[idx - 1]
 scalar z1 = zGrid[idx]
 scalar factor = (z - z0) / Foam::max(z1 - z0, 1e-12)
 return data[idx - 1] + factor * (data[idx] - data[idx - 1])
}


void turbulentDFMVeerInletFvPatchVectorField::initData
{
 if (initialized_)
 {
 return
 }

 const fileName dataDir =
 this->db.time.constant / "boundaryData" / this->patch.name
 pointField pts
 readBoundaryFile(dataDir / "points", pts)
 readBoundaryFile(dataDir / "U", UProfile_)
 readBoundaryFile(dataDir / "R", RProfile_)
 readBoundaryFile(dataDir / "L", LProfile_)
 readBoundaryFile(dataDir / "psi", psiProfile_)
 const label nPoints = pts.size
 if (nPoints == 0)
 {
 FatalErrorInFunction
 << "No profile points found in " << dataDir << exit(FatalError)
 }

 // Sort nodes strictly by vertical coordinate z
 struct ProfileNode
 {
 scalar z
 scalar U
 scalar psi
 symmTensor R
 tensor L
 }
 List<ProfileNode> nodes(nPoints)
 forAll(pts, i)
 {
 nodes[i].z = pts[i].z
 nodes[i].U = UProfile_[i]
 nodes[i].psi = psiProfile_[i]
 nodes[i].R = RProfile_[i]
 nodes[i].L = LProfile_[i]
 }

 std::sort
 (
 nodes.begin
 nodes.end
 [](const ProfileNode& a, const ProfileNode& b)
 {
 return a.z < b.z
 }
)
 zProfile_.setSize(nPoints)
 UProfile_.setSize(nPoints)
 psiProfile_.setSize(nPoints)
 RProfile_.setSize(nPoints)
 LProfile_.setSize(nPoints)
 forAll(nodes, i)
 {
 zProfile_[i] = nodes[i].z
 UProfile_[i] = nodes[i].U
 psiProfile_[i] = nodes[i].psi
 RProfile_[i] = nodes[i].R
 LProfile_[i] = nodes[i].L
 }

 // Correctly query face centres using Cf
 const vectorField& Cf = this->patch.Cf
 const label nFaces = this->patch.size
 UFace_.setSize(nFaces)
 psiRadFace_.setSize(nFaces)
 RFace_.setSize(nFaces)
 LFace_.setSize(nFaces)
 vPrime_.setSize(nFaces, vector::zero)
 forAll(Cf, fI)
 {
 const scalar z = Cf[fI].z
 UFace_[fI] = interpolate1D(z, zProfile_, UProfile_)
 const scalar psiDeg = interpolate1D(z, zProfile_, psiProfile_)
 psiRadFace_[fI] = psiDeg * constant::mathematical::pi / 180.0
 RFace_[fI] = interpolate1D(z, zProfile_, RProfile_)
 LFace_[fI] = interpolate1D(z, zProfile_, LProfile_)
 }

 setupFilterWeights
 initialized_ = true
}


void turbulentDFMVeerInletFvPatchVectorField::setupFilterWeights
{
 const vectorField& Cf = this->patch.Cf
 const label nFaces = this->patch.size
 scalar yMin = VGREAT, yMax = -VGREAT
 scalar zMin = VGREAT, zMax = -VGREAT
 forAll(Cf, fI)
 {
 yMin = Foam::min(yMin, Cf[fI].y)
 yMax = Foam::max(yMax, Cf[fI].y)
 zMin = Foam::min(zMin, Cf[fI].z)
 zMax = Foam::max(zMax, Cf[fI].z)
 }
 const scalar ySpan = Foam::max(yMax - yMin, 1e-6)
 const scalar zSpan = Foam::max(zMax - zMin, 1e-6)
 filterWeights_.setSize(3)
 for (label comp = 0; comp < 3; ++comp)
 {
 filterWeights_[comp].setSize(nFaces)
 }

 forAll(Cf, i)
 {
 const scalar yi = Cf[i].y
 const scalar zi = Cf[i].z
 for (label comp = 0; comp < 3; ++comp)
 {
 // Tensor ordering:
 // comp 0 (x'): Ly = L.xy, Lz = L.xz
 // comp 1 (y'): Ly = L.yy, Lz = L.yz
 // comp 2 (z'): Ly = L.zy, Lz = L.zz
 scalar Ly = 1.0
 scalar Lz = 1.0
 if (comp == 0)
 {
 Ly = Foam::max(LFace_[i].xy, 1e-3)
 Lz = Foam::max(LFace_[i].xz, 1e-3)
 }
 else if (comp == 1)
 {
 Ly = Foam::max(LFace_[i].yy, 1e-3)
 Lz = Foam::max(LFace_[i].yz, 1e-3)
 }
 else
 {
 Ly = Foam::max(LFace_[i].zy, 1e-3)
 Lz = Foam::max(LFace_[i].zz, 1e-3)
 }

 const scalar rCutY = filterFactor_ * Ly
 const scalar rCutZ = filterFactor_ * Lz
 DynamicList<FilterNeighbor> nbrList
 scalar sumWeightSqr = 0.0
 forAll(Cf, j)
 {
 scalar dy = std::abs(yi - Cf[j].y)
 if (periodicInY_ && dy > 0.5 * ySpan)
 {
 dy = ySpan - dy
 }

 scalar dz = std::abs(zi - Cf[j].z)
 if (periodicInZ_ && dz > 0.5 * zSpan)
 {
 dz = zSpan - dz
 }

 if (dy <= rCutY && dz <= rCutZ)
 {
 scalar b = 0.0
 if (filterType_ == "gaussian")
 {
 b = std::exp
 (
 -constant::mathematical::pi
 * (sqr(dy) / (4.0 * sqr(Ly)) + sqr(dz) / (4.0 * sqr(Lz)))
)
 }
 else // exponential
 {
 b = std::exp(-0.5 * constant::mathematical::pi * (dy / Ly + dz / Lz))
 }

 if (b > 1e-6)
 {
 FilterNeighbor fn
 fn.index = j
 fn.weight = b
 nbrList.append(fn)
 sumWeightSqr += sqr(b)
 }
 }
 }

 // Normalization ensuring unit spatial variance
 const scalar invNorm = 1.0 / Foam::max(std::sqrt(sumWeightSqr), 1e-12)
 forAll(nbrList, k)
 {
 nbrList[k].weight *= invNorm
 }

 filterWeights_[comp][i].transfer(nbrList)
 }
 }
}


// * * * * * * * * * * * * * * * Member Functions * * * * * * * * * * * * * //

void turbulentDFMVeerInletFvPatchVectorField::updateCoeffs
{
 if (this->updated)
 {
 return
 }

 initData
 const label timeIndex = this->db.time.timeIndex
 if (curTimeIndex_ != timeIndex)
 {
 curTimeIndex_ = timeIndex
 const label nFaces = this->patch.size
 const scalar dt = this->db.time.deltaTValue
 // 1. Generate independent 2D standard Gaussian white noise on all faces
 List<scalarField> whiteNoise(3)
 for (label comp = 0; comp < 3; ++comp)
 {
 whiteNoise[comp].setSize(nFaces)
 forAll(whiteNoise[comp], fI)
 {
 whiteNoise[comp][fI] = rnd_.scalarNormal
 }
 }

 // 2. Spatial filtering to obtain unit-variance correlated fields Psi
 List<scalarField> psiSpat(3)
 for (label comp = 0; comp < 3; ++comp)
 {
 psiSpat[comp].setSize(nFaces, 0.0)
 for (label fI = 0; fI < nFaces; ++fI)
 {
 const auto& nbrs = filterWeights_[comp][fI]
 scalar val = 0.0
 for (const auto& nbr : nbrs)
 {
 val += nbr.weight * whiteNoise[comp][nbr.index]
 }
 psiSpat[comp][fI] = val
 }
 }

 // 3. Time filtering (AR(1) process) for uncorrelated fluctuations v'
 for (label fI = 0; fI < nFaces; ++fI)
 {
 const scalar U = Foam::max(UFace_[fI], 1e-3)
 // Streamwise integral length scales: L.xx, L.yx, L.zx
 const scalar tau0 = Foam::max(LFace_[fI].xx / U, 1e-4)
 const scalar tau1 = Foam::max(LFace_[fI].yx / U, 1e-4)
 const scalar tau2 = Foam::max(LFace_[fI].zx / U, 1e-4)
 const scalar alpha0 = std::exp(-0.5 * constant::mathematical::pi * dt / tau0)
 const scalar alpha1 = std::exp(-0.5 * constant::mathematical::pi * dt / tau1)
 const scalar alpha2 = std::exp(-0.5 * constant::mathematical::pi * dt / tau2)
 vPrime_[fI].x = alpha0 * vPrime_[fI].x
 + std::sqrt(Foam::max(1.0 - sqr(alpha0), 0.0)) * psiSpat[0][fI]
 vPrime_[fI].y = alpha1 * vPrime_[fI].y
 + std::sqrt(Foam::max(1.0 - sqr(alpha1), 0.0)) * psiSpat[1][fI]
 vPrime_[fI].z = alpha2 * vPrime_[fI].z
 + std::sqrt(Foam::max(1.0 - sqr(alpha2), 0.0)) * psiSpat[2][fI]
 }

 // 4. Reynolds stress transformation (Cholesky) & rotation by veer angle psi
 vectorField uInlet(nFaces)
 for (label fI = 0; fI < nFaces; ++fI)
 {
 const symmTensor& R = RFace_[fI]
 const vector& v = vPrime_[fI]
 // Cholesky decomposition: A * A^T = R
 const scalar A00 = std::sqrt(Foam::max(R.xx, 1e-10))
 const scalar A10 = R.xy / A00
 const scalar A11 = std::sqrt(Foam::max(R.yy - sqr(A10), 1e-10))
 const scalar A20 = R.xz / A00
 const scalar A21 = (R.yz - A10 * A20) / A11
 const scalar A22 = std::sqrt(Foam::max(R.zz - sqr(A20) - sqr(A21), 1e-10))
 // Fluctuations in local wind-aligned frame (x', y', z')
 const vector uPrimeLocal
 (
 A00 * v.x
 A10 * v.x + A11 * v.y
 A20 * v.x + A21 * v.y + A22 * v.z
)
 // Rotate by veer angle psi around +z to global Cartesian frame (x, y, z)
 const scalar psi = psiRadFace_[fI]
 const scalar cosPsi = std::cos(psi)
 const scalar sinPsi = std::sin(psi)
 const vector uPrimeGlobal
 (
 uPrimeLocal.x * cosPsi - uPrimeLocal.y * sinPsi
 uPrimeLocal.x * sinPsi + uPrimeLocal.y * cosPsi
 uPrimeLocal.z
)
 // Mean velocity vector: U(z) * (cos psi, sin psi, 0)
 const scalar U = UFace_[fI]
 const vector uMean(U * cosPsi, U * sinPsi, 0.0)
 uInlet[fI] = uMean + uPrimeGlobal
 }

 this->operator==(uInlet)
 }

 fixedValueFvPatchVectorField::updateCoeffs
}


void turbulentDFMVeerInletFvPatchVectorField::write(Ostream& os) const
{
 fvPatchVectorField::write(os)
 os.writeKeyword("filterType") << filterType_ << token:[已隐去] << nl
 os.writeKeyword("filterFactor") << filterFactor_ << token:[已隐去] << nl
 os.writeKeyword("periodicInY") << periodicInY_ << token:[已隐去] << nl
 os.writeKeyword("periodicInZ") << periodicInZ_ << token:[已隐去] << nl
 os.writeKeyword("constMeanU") << constMeanU_ << token:[已隐去] << nl
 os.writeKeyword("Uref") << Uref_ << token:[已隐去] << nl
 writeEntry(os, "value", *this)
}

